#!/usr/bin/env bash
# Build landing promo videos from the HyperFrames master renders.
#
# For each concept and language:
#   master  $HF_DIR/ac-<concept>/renders/<lang>.mp4   (1080x1080, silent; outside git)
#   music   videos/<concept>/music.mp3                (in git; generated by toolbox/music)
#   ->      $HF_DIR/ac-<concept>/renders/<lang>-music.mp4   1080 master with music (social)
#   ->      public/video/<lang>/<concept>.mp4                720x720 web copy with music
#   ->      public/video/<lang>/<concept>.jpg                poster
#
# Runs inside WSL (masters live on the WSL disk); ffmpeg only, no browser.
# Idempotent: an output is rebuilt only when it is missing or older than its inputs; FORCE=1 rebuilds all.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
HF_DIR="${HF_DIR:-$HOME/hf}"
FORCE="${FORCE:-}"
CONCEPTS=(odometer holiday invitation numbers newspaper)
LANGS=(ru en)

# Poster frame (seconds) per concept: a moment that reads well as a still.
poster_at() {
  case "$1" in
    odometer) echo 6 ;; holiday) echo 8 ;; invitation) echo 12 ;; numbers) echo 12 ;; newspaper) echo 7.5 ;;
    *) echo 5 ;;
  esac
}

command -v ffmpeg >/dev/null || { echo "ERROR: ffmpeg not found" >&2; exit 2; }

stale() { # stale <out> <in>...
  local out="$1"; shift
  [[ -n "$FORCE" || ! -f "$out" ]] && return 0
  local f; for f in "$@"; do [[ "$f" -nt "$out" ]] && return 0; done
  return 1
}

built=0; skipped=0
for c in "${CONCEPTS[@]}"; do
  music="$ROOT/videos/$c/music.mp3"
  [[ -f "$music" ]] || { echo "ERROR: missing $music" >&2; exit 1; }
  for l in "${LANGS[@]}"; do
    master="$HF_DIR/ac-$c/renders/$l.mp4"
    [[ -f "$master" ]] || { echo "ERROR: missing master render $master" >&2; exit 1; }
    mixed="$HF_DIR/ac-$c/renders/$l-music.mp4"
    web="$ROOT/public/video/$l/$c.mp4"
    poster="$ROOT/public/video/$l/$c.jpg"
    mkdir -p "$(dirname "$web")"

    if stale "$mixed" "$master" "$music"; then
      ffmpeg -v error -y -i "$master" -i "$music" -map 0:v:0 -map 1:a:0 -c:v copy \
        -c:a aac -b:a 192k -shortest -movflags +faststart "$mixed"
    fi
    if stale "$web" "$mixed"; then
      ffmpeg -v error -y -i "$mixed" -vf "scale=720:720:flags=lanczos,format=yuv420p" \
        -c:v libx264 -preset slow -crf 27 -profile:v high -c:a aac -b:a 96k -ac 2 \
        -movflags +faststart "$web"
      built=$((built + 1))
    else
      skipped=$((skipped + 1))
    fi
    if stale "$poster" "$master"; then
      ffmpeg -v error -y -ss "$(poster_at "$c")" -i "$master" -frames:v 1 -vf "scale=720:720:flags=lanczos" -q:v 4 "$poster"
    fi
    printf '%-10s %s  %s KB\n' "$c" "$l" "$(( $(stat -c%s "$web") / 1024 ))"
  done
done
echo "built=$built skipped=$skipped"
